443	/// A verdict as a complaint's last-run summary may carry it: one of the reply schema's verdicts,
444	/// `none` without one, else `other`.
445	pub(crate) fn verdict_class(verdict: &str) -> String {
446	    let v = verdict.trim();
447	    if v.is_empty() {
448	        "none".into()
449	    } else if ["ACCEPT", "HOLD", "REJECT", "ADVISE"].contains(&v) {
450	        v.into()
451	    } else {
452	        "other".into()
453	    }
454	}
