458	/// `Get-TelemetryConsultRef`: the entry's `consult_ref`, lower-cased, only when it has the shape of
459	/// a guid; `None` for an entry without one (recorded before 0.6.1) or with anything else.
460	pub fn consult_ref_of(entry: &LedgerEntry) -> Option<String> {
461	    let v = entry.consult_ref.as_deref()?.trim().to_ascii_lowercase();
462	    is_guid(&v).then_some(v)
463	}
464	
465	/// `^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$` (lower case).
466	pub(crate) fn is_guid(v: &str) -> bool {
467	    let parts: Vec<&str> = v.split('-').collect();
468	    parts.len() == 5
469	        && [8, 4, 4, 4, 12]
470	            .iter()
471	            .zip(&parts)
472	            .all(|(n, p)| p.len() == *n && p.chars().all(|c| matches!(c, '0'..='9' | 'a'..='f')))
473	}
