672	/// `Get-TelemetryRatingActor`: the judge of a mark given NOW - `CODEX_CONSULT_COORDINATOR` of THIS
673	/// process, resolved exactly as the bridge resolves it for the ledger's coordinator record (with the
674	/// reviewer roster and the Codex config's defaults - `c3_core::host::resolve_coordinator_identity`;
675	/// the host hint of this process), classified by [`judge_class`] - source
676	/// `rating_actor`. A value that does not parse names an actor no class fits: `other / other`.
677	/// `None` when the variable is unset or empty (the consultation's own coordinator decides then).
678	pub fn rating_actor() -> Option<Judge> {
679	    let v = std::env::var("CODEX_CONSULT_COORDINATOR").unwrap_or_default();
680	    let v = v.trim();
681	    if v.is_empty() {
682	        return None;
683	    }
684	    let none = Judge {
685	        provider: "other".into(),
686	        model: "other".into(),
687	        source: "rating_actor".into(),
688	    };
689	    let roster = crate::providers::read_reviewer_roster().ok();
690	    let entries = roster.as_ref().filter(|r| r.exists).map(|r| &r.entries[..]);
691	    let config = crate::providers::read_codex_config(&crate::providers::get_codex_config_path());
692	    // (F09-6) the bridge's own resolver - a bare label takes its roster entries' one model, a
693	    // model-less entry the configured model - never a second, thinner parse
694	    let Ok(record) = c3_core::host::resolve_coordinator_identity(
695	        v,
696	        entries,
697	        &c3_core::host::codex_config_defaults(&config),
698	        c3_core::host::coordinator_host(),
699	    ) else {
700	        return Some(none);
701	    };
702	    let (provider, model) = judge_class(
703	        &CoordinatorView::of(&record),
704	        roster.as_ref(),
705	        Some(&config),
706	    );
707	    Some(Judge {
708	        provider,
709	        model,
710	        source: "rating_actor".into(),
711	    })
712	}
