827	/// An instance id of this client's shape: the 64 lower-case hex digits of a SHA-256.
828	fn is_instance_id(v: &str) -> bool {
829	    v.len() == 64 && v.chars().all(|c| matches!(c, '0'..='9' | 'a'..='f'))
830	}
