100	/// One window of a `rate_limits` object as the ledger records it: `{used_percent, window_minutes,
101	/// resets_at}` (`resets_at` ISO with the LOCAL offset, from unix seconds).
102	#[derive(Debug, Clone, PartialEq)]
103	pub struct Window {
104	    pub used_percent: f64,
105	    pub window_minutes: Option<i64>,
106	    pub resets_at: Option<String>,
107	}
108	
109	impl Window {
110	    /// The ledger's shape.
111	    pub fn to_json(&self) -> Value {
112	        json!({
113	            "used_percent": self.used_percent,
114	            "window_minutes": self.window_minutes,
115	            "resets_at": self.resets_at,
116	        })
117	    }
118	}
