240	/// One `token_count` event (`Get-RolloutTokenEvents`).
241	#[derive(Debug, Clone)]
242	struct TokenEvent {
243	    at: Option<DateTime<FixedOffset>>,
244	    total: Option<Totals>,
245	    /// The raw total: a new call changes it.
246	    total_key: Option<Value>,
247	    last_input: Option<i64>,
248	    context_window: Option<i64>,
249	    has_limits: bool,
250	    limit_id: String,
251	    primary: Option<Window>,
