465	fn uuid_re() -> &'static regex::Regex {
466	    static RE: OnceLock<regex::Regex> = OnceLock::new();
467	    RE.get_or_init(|| {
468	        regex::Regex::new(
469	            r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}",
470	        )
471	        .unwrap()
472	    })
473	}
474	
475	fn is_uuid(s: &str) -> bool {
476	    s.len() == 36 && uuid_re().find(s).map(|m| m.as_str() == s).unwrap_or(false)
477	}
