1085	/// [`account_window`] judged at the one comparison instant `now`.
1086	pub fn account_window_at(codex_home: &str, now: DateTime<Utc>) -> Option<AccountWindow> {
1087	    if codex_home.is_empty() {
1088	        return None;
1089	    }
1090	    let cached = account_cache().lock().ok().and_then(|c| {
1091	        c.get(codex_home)
1092	            .filter(|(at, _)| at.elapsed().as_secs() < 60)
1093	            .map(|(_, v)| v.clone())
1094	    });
1095	    let observations = match cached {
1096	        Some(v) => v,
1097	        None => {
1098	            let v = read_account_observations(codex_home);
1099	            if let Ok(mut c) = account_cache().lock() {
1100	                c.insert(codex_home.to_string(), (Instant::now(), v.clone()));
1101	            }
1102	            v
1103	        }
1104	    };
1105	    let mut best: Option<Observation> = None;
1106	    let mut best_path = PathBuf::new();
1107	    for (o, p) in &observations {
1108	        let before = best.clone();
1109	        best = merge_observation(best, Some(o), now);
1110	        if best != before {
1111	            best_path = p.clone();
1112	        }
1113	    }
1114	    best.filter(|b| b.named() && b.at.is_some())
1115	        .map(|b| AccountWindow {
1116	            quota: b.to_quota(),
1117	            observed_at: b.at.unwrap(),
1118	            window_at: [
1119	                b.primary.as_ref().and(b.window_at(0)),
1120	                b.secondary.as_ref().and(b.window_at(1)),
1121	            ],
1122	            path: best_path,
1123	        })
1124	}
