1126	/// The observations of the account's last 16 rollouts (today and yesterday, local) on the built-in
1127	/// `openai` provider that name a window - read from disk, no selection.
1128	fn read_account_observations(codex_home: &str) -> Vec<(Observation, PathBuf)> {
1129	    let mut out = Vec::new();
1130	    let root = Path::new(codex_home).join("sessions");
1131	    if !root.is_dir() {
1132	        return out;
1133	    }
1134	    let today = Local::now().date_naive();
1135	    let mut files: Vec<(SystemTime, PathBuf)> = Vec::new();
1136	    for d in local_day_dirs(&root, today.pred_opt().unwrap_or(today), today) {
1137	        rollouts_in(&d, None, &mut files);
1138	    }
1139	    files.sort_by_key(|(t, _)| std::cmp::Reverse(*t));
1140	    let provider_re = regex::Regex::new(r#""model_provider"\s*:\s*"([^"]*)""#).unwrap();
1141	    for (_, p) in files.into_iter().take(16) {
1142	        let head = read_rollout_head(&p);
1143	        if let Some(c) = provider_re.captures(&head) {
1144	            if &c[1] != "openai" {
1145	                continue;
1146	            }
1147	        }
1148	        let u = rollout_usage(&p, None, ROLLOUT_TAIL_BYTES);
1149	        if let Some(w) = u.window {
1150	            out.push((w, p));
1151	        }
1152	    }
1153	    out
1154	}
