1288	/// Write each retained window's instant into the selected `quota` (the keys of [`WINDOW_AT_KEYS`]).
1289	fn stamp_window_instants(w: &mut EndpointWindow) {
1290	    for (k, key) in WINDOW_AT_KEYS.iter().enumerate() {
1291	        match (
1292	            w.window_at[k],
1293	            quota_used(&w.quota, ["primary", "secondary"][k]),
1294	        ) {
1295	            (Some(t), Some(_)) if !w.window_legacy[k] => {
1296	                w.quota[*key] = Value::String(iso_instant(to_local(t)))
1297	            }
1298	            _ => {
1299	                if let Some(o) = w.quota.as_object_mut() {
1300	                    o.remove(*key);
1301	                }
1302	            }
1303	        }
1304	    }
1305	}
