1307	/// `Get-EndpointWindow`: every consultation (ledger entry or machine-wide record) of `fp_set` that
1308	/// carries a `quota` naming a window (its `observed_at`, else the entry's `finished_at`, else its
1309	/// `when`, orders them) and - when the live source is on and the set holds the built-in openai
1310	/// endpoint - the newest rollout of the codex home ([`account_window`]).
1311	pub fn endpoint_window(
1312	    consults: &[Value],
1313	    fp_set: &[&str],
1314	    builtin_fingerprint: &str,
1315	) -> Option<EndpointWindow> {
