    }

    fn v7(at: DateTime<Utc>, salt: u32) -> String {
        let ms = format!("{:012x}", at.timestamp_millis());
        format!(
            "{}-{}-7{:03x}-8{:03x}-{:012x}",
            &ms[0..8],
            &ms[8..12],
            salt & 0xfff,
            (salt >> 3) & 0xfff,
            salt as u64 * 7919
        )
    }

