        let q84 = json!({"primary": {"used_percent": 84.0, "window_minutes": 300, "resets_at": "2026-10-13T16:32:16+00:00"}, "secondary": null});
        assert_eq!(
            format_low_warning(&q84, clock),
            format!("low quota: 5-hour window 84 % until {lt}")
