/// One telemetry event: the exact T-hub event shape (README "The event"), the top level in the
/// plugin's order.
#[derive(Debug, Clone, Serialize)]
pub struct Event {
    pub app_id: &'static str,
    pub app_version: &'static str,
    pub instance_id: String,
    pub event_type: &'static str,
    /// `info` (a usable reply), `warning` (auth, quota, operator) or `error` (every other failure).
    pub severity: &'static str,
    /// The purpose class (the same value as `details.purpose`).
    pub title: String,
    pub details: Details,
    /// `[provider, model]` - the same two classes as `details`.
    pub tags: Vec<String>,
    /// RFC 3339 UTC, seconds precision.
    pub client_time: String,
    pub os: String,
    pub runtime: String,
}

/// The `details` object: the typed allowlist. Field order matches the public keys the
/// T-hub page shows (README "The event").
#[derive(Debug, Clone, Serialize)]
pub struct Details {
    /// `codex | agy | muse | claude | http | other`.
    pub engine: String,
    /// The vendor CLASS of the endpoint (`classes::reviewer_class`), else `other`.
    pub provider: String,
    /// Model label (safe) or `unknown`.
    pub model: String,
    /// Purpose label (safe) or `unknown`.
    pub purpose: String,
    /// `usable` or `failed:<class>`.
    pub outcome: String,
    pub wall_seconds: f64,
    pub tokens_in: i64,
    pub tokens_out: i64,
    pub findings: i64,
    pub structured: bool,
    pub format_retry: bool,
    pub panel_size: u32,
    /// (M11) How many federation peers contributed to this consultation's pack — a COUNT only,
    /// never a name, a path or a connection string. Nothing federated ever reaches the hub.
    pub peers_used: u32,
    pub os: String,
    pub runtime: String,
    /// A tag from a fixed vocabulary; `None` for now (DESIGN §8). Never free text.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub topic_tag: Option<String>,
    /// The coordinator's usefulness mark (`yes | partly | no`) once known; else absent.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub useful: Option<String>,
    /// Verified finding count once findings settle; else absent.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub verified: Option<i64>,
    /// Rejected finding count once findings settle; else absent.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub rejected: Option<i64>,
    /// (0.6.1, U5) The ledger entry's `consult_ref` - the random id that links this consultation to
    /// its rating events - LAST, only when the entry has one (an entry recorded before 0.6.1 has
    /// none, and its event no such key).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub consult_ref: Option<String>,
}

impl Event {
    /// Build the event for one consultation from its ledger entry. `panel_size` is the
    /// coordinator's known seat count; when `None` it falls back to `entry.panel.of` or 1.
    /// `instance_id` is passed in so the caller controls when the salt file is touched.
    pub fn from_ledger(entry: &LedgerEntry, panel_size: Option<u32>, instance_id: &str) -> Self {
        let purpose = classes::purpose_class(&entry.purpose);
        let (engine, provider, model) = classes::reviewer_class(entry);
        let (outcome, severity) = classes::outcome_class(entry);
        let (tokens_in, tokens_out) = entry
            .usage
            .as_ref()
            .map(|u| (u.input_tokens, u.output_tokens))
            .unwrap_or((0, 0));
        let findings = entry.findings.blocker
            + entry.findings.major
            + entry.findings.minor
            + entry.findings.note;
        let panel_size = panel_size.unwrap_or_else(|| {
            entry
                .panel
                .as_ref()
                .map(|p| p.of)
                .filter(|&of| of > 0)
                .map(|of| of as u32)
                .unwrap_or(1)
        });
        let details = Details {
            engine,
            provider,
            model,
            purpose: purpose.clone(),
            outcome,
            wall_seconds: entry.wall_seconds,
            tokens_in,
            tokens_out,
            findings,
            structured: entry.structured,
            format_retry: entry
                .format_retry
                .as_ref()
                .map(|f| f.attempted)
                .unwrap_or(false),
            panel_size,
            // (M11) the COUNT of federation peers brought into this consultation's pack — read
            // from the http seat's `reviewer.provider_config.peers` (an integer, never a name); 0
            // when no peers were used (the field is absent).
            peers_used: entry
                .reviewer
                .provider_config
                .get("peers")

