pub const VALID: [&str; 8] = [
    "framing",
    "decision",
    "checkpoint",
    "core-contract",
    "acceptance",
    "diff-review",
    "stuck",
    "chore",
];

/// The default effort for a purpose (`""` = no purpose).
pub fn effort(purpose: &str) -> &'static str {
    match purpose {
        "framing" | "decision" | "acceptance" | "diff-review" => "high",
        "checkpoint" => "medium",
        "core-contract" | "stuck" => "xhigh",
        "chore" => "low",
        _ => "high",
    }
}

/// The default word budget for a purpose.
pub fn words(purpose: &str) -> u32 {
    match purpose {
        "checkpoint" => 500,
        "core-contract" | "acceptance" => 900,
        "chore" => 400,
        _ => 700,
    }
}

/// The default timeout (seconds) for a purpose (`""` = no purpose → 900).
pub fn timeout(purpose: &str) -> i64 {
    match purpose {
        "framing" | "decision" => 1800,
        "core-contract" | "diff-review" | "stuck" => 2400,
        "acceptance" => 3600,
        "chore" => 600,
        _ => 900,
    }
}

/// The purpose paragraph appended to the prompt. (wave 8 = plugin wave 30, T15) The paragraphs
/// of the reviewing purposes (checkpoint, core-contract, acceptance, diff-review) end with the

pub struct RatingEvent {
    pub app_id: &'static str,
    pub app_version: &'static str,
    pub instance_id: String,
    pub event_type: &'static str,
    pub severity: &'static str,
    pub title: String,
    pub details: RatingDetails,
    pub tags: Vec<String>,
    pub client_time: String,
    pub os: String,
    pub runtime: String,
}

/// The `details` allowlist of a rating event, in the plugin's exact order
/// (`$script:TelemetryRatingDetailKeys`): `engine, provider, model, purpose, mark, age_days,
/// bridge_version, os, ps_version, judge`, then `rating_rev` (a mark rated since 0.6.1) and
/// `consult_ref` (an entry recorded since 0.6.1) when present.
#[derive(Debug, Clone, Serialize)]
pub struct RatingDetails {
    pub engine: String,
    pub provider: String,
    pub model: String,
    pub purpose: String,
    /// `yes | partly | no` (anything else `other`).
    pub mark: String,
    /// The whole days from the consultation's time to the mark's (`0` the same day).
    pub age_days: i64,
    /// The C3 version.
    pub bridge_version: String,
    pub os: String,
    /// The plugin's `$PSVersionTable.PSVersion` token; C3 runs no PowerShell: `unknown` (the
    /// plugin's own rule for an empty value).
    pub ps_version: String,
    /// `{provider, model, source}` - classes only.
    pub judge: Judge,
    /// (F06-2) The mark's own revision among its consultation's marks (>= 1).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub rating_rev: Option<i64>,
    /// (U5) The rated entry's `consult_ref`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub consult_ref: Option<String>,
}

/// What a rating event is built from: the rated ledger entry and the MARK as saved.
